import { Button } from '@dynatrace/strato-components/buttons';
import { AppRoot } from '@dynatrace/strato-components/core';
import {
  FormField,
  Label,
  TextInput,
} from '@dynatrace/strato-components/forms';
import { Flex } from '@dynatrace/strato-components/layouts';
import { Paragraph } from '@dynatrace/strato-components/typography';
import React, { useState } from 'react';
import { createRoot } from 'react-dom/client';

const ActionNameSettingsWidget = () => {
  const [name, setName] = useState('');
  const [savedName, setSavedName] = useState('');

  const saveValue = () => {
    // Persist the value for the "action-name-connection" schema here, for example with
    // appSettingsObjectsClient from "@dynatrace-sdk/client-app-settings-v2"
    // (this requires the "app-settings:objects:write" scope).
    setSavedName(name);
  };

  return (
    <Flex flexDirection="column" gap={16} alignItems="flex-start">
      <FormField>
        <Label>Name</Label>
        <TextInput
          value={name}
          onChange={(value: string) => setName(value)}
          placeholder="Enter a name"
        />
      </FormField>
      <Button
        variant="emphasized"
        color="primary"
        onClick={saveValue}
        disabled={!name}
      >
        Save
      </Button>
      {savedName && <Paragraph>Saved value: {savedName}</Paragraph>}
    </Flex>
  );
};

// Settings widgets are their own entry point — they mount themselves into `#root`.
// The guard keeps the module importable from tests, where no `#root` element exists.
const rootElement = document.getElementById('root');
if (rootElement) {
  createRoot(rootElement).render(
    <AppRoot>
      <ActionNameSettingsWidget />
    </AppRoot>,
  );
}

export default ActionNameSettingsWidget;
